let language='ja',messages={};
export function t(key,values={}) {const bad=/^TXTの(\d+)行目の音名が不正です：(.*)$/.exec(key);if(bad)return t('badNoteAt',{line:bad[1],note:bad[2]});return (messages[key]??key).replace(/\{(\w+)\}/g,(_,name)=>String(values[name]??`{${name}}`));}
export function currentLanguage(){return language;}
export function preferredLanguage(){try{const saved=localStorage.getItem('score-language');if(['ja','en'].includes(saved))return saved;}catch{}return navigator.language?.startsWith('en')?'en':'ja';}
export async function loadLanguage(next){if(!['ja','en'].includes(next))throw new Error('翻訳を読み込めませんでした。');const response=await fetch(`locales/${next}.json`,{cache:'no-cache'});if(!response.ok)throw new Error('翻訳を読み込めませんでした。');const loaded=await response.json();language=next;messages=loaded;document.documentElement.lang=next;try{localStorage.setItem('score-language',next);}catch{} }
export function localized(metadata,key,fallback=''){return metadata[`${key}_${language}`]||metadata[key]||Object.entries(metadata).find(([name,value])=>name.startsWith(key+'_')&&value)?.[1]||fallback;}
export function translatePage(){for(const element of document.querySelectorAll('[data-i18n]'))element.textContent=t(element.dataset.i18n);for(const element of document.querySelectorAll('[data-i18n-title]'))element.title=t(element.dataset.i18nTitle);for(const element of document.querySelectorAll('[data-i18n-label]'))element.setAttribute('aria-label',t(element.dataset.i18nLabel));document.title=t('pageTitle');const description=document.querySelector('meta[name="description"]');if(description)description.content=t('pageDescription');}
